package com.fakelegacy.order.pricing;

import java.math.BigDecimal;
import java.util.List;

public class PricingResult {

    private final List<LineDraft> lines;
    private BigDecimal goodsHt = BigDecimal.ZERO.setScale(2);
    private BigDecimal goodsTtc = BigDecimal.ZERO.setScale(2);
    private boolean capApplied;

    public PricingResult(List<LineDraft> lines) {
        this.lines = lines;
    }

    public void recomputeTotals() {
        BigDecimal ht = BigDecimal.ZERO.setScale(2);
        BigDecimal ttc = BigDecimal.ZERO.setScale(2);
        for (LineDraft l : lines) {
            l.recompute();
            ht = ht.add(l.getLineHt());
            ttc = ttc.add(l.getLineTtc());
        }
        goodsHt = ht;
        goodsTtc = ttc;
    }

    public List<LineDraft> getLines() { return lines; }
    public BigDecimal getGoodsHt() { return goodsHt; }
    public BigDecimal getGoodsTtc() { return goodsTtc; }

    public boolean isCapApplied() { return capApplied; }
    public void setCapApplied(boolean capApplied) { this.capApplied = capApplied; }
}
